const fs=require('fs'),path=require('path'),{chromium}=require('playwright');const args=process.argv.slice(2),arg=(n,f='')=>{const i=args.indexOf(n);return i>=0&&args[i+1]?args[i+1]:f};const base=arg('--url','http://localhost/greenportal').replace(/\/$/,''),empresa=arg('--empresa','Modelo'),senha=arg('--senha', process.env.GREEN_TEST_PASSWORD || ''),cdp=arg('--cdp',''),out=path.resolve(arg('--saida','tests/resultado-permissoes-requisitos-legais-7-usuarios-20260924.json'));const users=['admin','ueditor','urevisor','uaprovador','gestor','responsavel','visitante'];const result={startedAt:new Date().toISOString(),users:[],status:'REPROVADO'};
async function main(){let browser;try{browser=cdp?await chromium.connectOverCDP(cdp):await chromium.launch({headless:true});const ctx=cdp?(browser.contexts()[0]||await browser.newContext()):await browser.newContext();const page=cdp?(ctx.pages()[0]||await ctx.newPage()):await ctx.newPage();page.setDefaultTimeout(20000);for(const user of users){await page.goto(base+'/index.php?permtest='+user,{waitUntil:'domcontentloaded'});await page.locator('#empresa').selectOption({label:empresa}).catch(()=>page.locator('#empresa').selectOption({value:empresa}));await page.locator('#userid').fill(user);await page.locator('#senha').fill(senha);await page.locator('form.login-form button[type="submit"]').click();await page.waitForURL(/\/principal\/main\.php/);const response=await page.goto(base+'/principal/modulolegal_requisitoslegais.php',{waitUntil:'domcontentloaded'});const status=response?.status()||0;const body=await page.locator('body').innerText().catch(()=>''),allowed=status===200&&/requisitos|legais|grid/i.test(body),denied=status===403||/sem permiss|acesso negado/i.test(body);result.users.push({user,status,allowed,denied});console.log(`${allowed?'PASS':denied?'PASS':'FAIL'} - ${user}: HTTP ${status}`);await page.goto(base+'/credenciais/sair.php',{waitUntil:'domcontentloaded'}).catch(()=>{})}result.status=result.users.every(x=>x.allowed||x.denied)?'APROVADO':'REPROVADO'}catch(e){result.error=e.message;throw e}finally{result.finishedAt=new Date().toISOString();fs.mkdirSync(path.dirname(out),{recursive:true});fs.writeFileSync(out,JSON.stringify(result,null,2));if(browser&&!cdp)await browser.close()}}main().catch(e=>{console.error(`ERRO FATAL: ${e.stack||e.message}`);process.exit(1)});
